obs = primitives.call(name="observe_rlbench_scene", include_raw=False, prompt="close microwave")
print("obs ok:", obs.ok)
if obs.ok:
    tds = obs.output.get("object_pose_evidence", {}).get("task_low_dim_state", [])
    print("len(task_low_dim_state):", len(tds))
    for i in range(0, len(tds), 7):
        print(f"chunk {i//7} [{i}:{i+7}]:", [round(x, 4) for x in tds[i : i + 7]])

insp = primitives.call(
    name="inspect_rlbench_visual_evidence",
    camera_name="front",
    prompt="close microwave",
    query="microwave door",
    target_name="microwave door",
)
print("insp ok:", insp.ok)
if insp.ok:
    print("insp keys:", list(insp.output.keys()))
    for k in ["evidence_refs", "target_pose", "pose", "candidates", "mask_stats"]:
        if k in insp.output:
            print(k, ":", insp.output[k])

gnd = primitives.call(
    name="ground_rlbench_target", query="close the microwave door", target_name="microwave_door"
)
print("gnd ok:", gnd.ok)
if gnd.ok:
    print("gnd output:", gnd.output)
